sp_widget.client_script:
api.controller = function($scope) {
  var c = this;

  c.login = function() {
    c.server.update({
      username: c.data.username,
      password: c.data.password
    });
  };
};

sp_widget.script:
(function() {
  data.success = false;
  data.message = "";

  if (input && input.username && input.password) {
    var userGR = new GlideRecord("sys_user");
    userGR.addQuery("user_name", input.username);
    userGR.query();

    if (userGR.next()) {
      // Compare the input password with the encrypted one
      var enc = new GlideEncrypter();
      if (enc.checkPassword(input.password, userGR.password)) {
        data.success = true;
        data.message = "✅ Login successful for: " + userGR.name;
        // Optional: Set session (only works in full instance, not in SP by default)
        // GlideSession.get().setUserID(userGR.sys_id);
      } else {
        data.message = "❌ Incorrect password.";
      }
    } else {
      data.message = "❌ User not found.";
    }
  } else {
    data.message = "⚠️ Please enter both username and password.";
  }
})();
